function bp(y,i,u){const id=u?.id||`T${y}U${Number(i)+1}`;return DATA[id]||null}
function audit(){const ids=Object.keys(DATA), issues=[];for(let y=1;y<=6;y++){const ys=ids.filter(id=>id.startsWith(`T${y}U`));if(ys.length!==24)issues.push(`Y${y}: ${ys.length} units`)}for(const [id,b] of Object.entries(DATA)){if(b.vocab.length<6)issues.push(`${id}:vocab`);if(b.readings.length!==3)issues.push(`${id}:readings`);if(b.questions.length!==9)issues.push(`${id}:questions`);if(b.grammar.length!==3)issues.push(`${id}:grammar`);if(!b.writing.transfer||!b.writing.mastery)issues.push(`${id}:writing`);if(!b.masteryPolicy.independentRequired)issues.push(`${id}:mastery`)}return {version:'FULL-CONTENT-1.0',units:ids.length,readings:ids.length*3,questions:ids.length*9,grammarTasks:ids.length*3,issues,passed:issues.length===0}}
window.BAHASA_FULL_CONTENT={version:'FULL-CONTENT-1.0',records:DATA,get:(id)=>DATA[id]||null,audit};
